using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
            e.HasIndex(s => s.CustomerEmail);
        });
    }
}

builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();

builder.Services.AddScoped<IShipmentService, ServerShipmentService>();

var app = builder.Build();

// Seed sample data
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();
    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "ST-A1B2C3D4", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "customer@example.com", Description = "Electronics - 2 boxes", CreatedAt = DateTime.UtcNow.AddDays(-2), LastUpdated = DateTime.UtcNow },
            new Shipment { TrackingNumber = "ST-E5F6G7H8", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.Pending, EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "customer@example.com", Description = "Furniture - 1 pallet", CreatedAt = DateTime.UtcNow.AddDays(-1), LastUpdated = DateTime.UtcNow },
            new Shipment { TrackingNumber = "ST-I9J0K1L2", Origin = "Seattle, WA", Destination = "Denver, CO", Status = ShipmentStatus.OutForDelivery, EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "jane@example.com", Description = "Medical supplies", CreatedAt = DateTime.UtcNow.AddDays(-4), LastUpdated = DateTime.UtcNow },
            new Shipment { TrackingNumber = "ST-M3N4O5P6", Origin = "Boston, MA", Destination = "Houston, TX", Status = ShipmentStatus.Delivered, EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "jane@example.com", Description = "Auto parts - 3 crates", CreatedAt = DateTime.UtcNow.AddDays(-7), LastUpdated = DateTime.UtcNow.AddDays(-1) },
            new Shipment { TrackingNumber = "ST-Q7R8S9T0", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.PickedUp, EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "bob@example.com", Description = "Perishable goods", CreatedAt = DateTime.UtcNow, LastUpdated = DateTime.UtcNow }
        );
        db.SaveChanges();
    }
}

// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("", async (IShipmentService svc) =>
    Results.Ok(await svc.GetAllShipmentsAsync()));

shipments.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
{
    var shipment = await svc.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

shipments.MapGet("customer/{email}", async (string email, IShipmentService svc) =>
    Results.Ok(await svc.GetShipmentsByCustomerAsync(email)));

shipments.MapPost("", async (ShipmentDto dto, IShipmentService svc) =>
{
    var created = await svc.CreateShipmentAsync(dto);
    return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
});

shipments.MapPut("{id}/status", async (int id, StatusUpdateRequest req, IShipmentService svc) =>
{
    var updated = await svc.UpdateShipmentStatusAsync(id, req.Status);
    return updated is null ? Results.NotFound() : Results.Ok(updated);
});

// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

