@page "/shipments"
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container mt-4">
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h2>🚚 Dispatcher Dashboard</h2>
        <button class="btn btn-primary" @onclick="ToggleNewShipmentForm">
            @(showNewForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>

    @if (showNewForm)
    {
        <div class="card mb-4 shadow-sm">
            <div class="card-body">
                <h5 class="card-title">Create New Shipment</h5>
                <div class="row g-3">
                    <div class="col-md-6">
                        <label class="form-label">Origin</label>
                        <input class="form-control" @bind="newShipment.Origin" placeholder="e.g. New York, NY" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Destination</label>
                        <input class="form-control" @bind="newShipment.Destination" placeholder="e.g. Los Angeles, CA" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Customer Email</label>
                        <input class="form-control" type="email" @bind="newShipment.CustomerEmail" placeholder="customer@example.com" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Estimated Delivery</label>
                        <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-12">
                        <label class="form-label">Description</label>
                        <input class="form-control" @bind="newShipment.Description" placeholder="Package description" />
                    </div>
                    <div class="col-12">
                        <button class="btn btn-success" @onclick="CreateShipment" disabled="@isCreating">
                            @(isCreating ? "Creating..." : "Create Shipment")
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }

    <div class="row mb-3">
        <div class="col-md-4">
            <input class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="filterStatus">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
    </div>

    @if (shipments is null)
    {
        <div class="text-center py-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filter.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Customer</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><code>@s.TrackingNumber</code></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                            <td>@s.CustomerEmail</td>
                            <td>
                                <select class="form-select form-select-sm"
                                        value="@s.Status"
                                        @onchange="e => UpdateStatus(s.Id, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string filterStatus = "";
    private bool showNewForm;
    private bool isCreating;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(filterText)
                || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase))
            && (string.IsNullOrEmpty(filterStatus)
                || s.Status.ToString() == filterStatus));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ToggleNewShipmentForm() => showNewForm = !showNewForm;

    private async Task CreateShipment()
    {
        isCreating = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
            showNewForm = false;
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2 class="mb-4">🔍 Track a Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input class="form-control form-control-lg" placeholder="Enter tracking number (e.g. ST-A1B2C3D4)"
                       @bind="trackingNumber" @onkeyup="HandleKeyUp" />
                <button class="btn btn-primary btn-lg" @onclick="Search" disabled="@isSearching">
                    @(isSearching ? "Searching..." : "Track")
                </button>
            </div>
        </div>
    </div>

    @if (searched && shipment is null)
    {
        <div class="alert alert-warning">
            No shipment found with tracking number <strong>@searchedNumber</strong>. Please check and try again.
        </div>
    }

    @if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header bg-dark text-white d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Shipment <code class="text-light">@shipment.TrackingNumber</code></h5>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row g-4">
                    <div class="col-md-6">
                        <h6 class="text-muted">Route</h6>
                        <p class="fs-5">@shipment.Origin → @shipment.Destination</p>
                    </div>
                    <div class="col-md-6">
                        <h6 class="text-muted">Description</h6>
                        <p class="fs-5">@shipment.Description</p>
                    </div>
                    <div class="col-md-6">
                        <h6 class="text-muted">Estimated Delivery</h6>
                        <p class="fs-5">
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <span>@shipment.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</span>
                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                                {
                                    var daysLeft = (shipment.EstimatedDelivery.Value.Date - DateTime.UtcNow.Date).Days;
                                    <br />
                                    <small class="text-muted">
                                        @if (daysLeft > 0) { <text>@daysLeft day(s) away</text> }
                                        else if (daysLeft == 0) { <text>Expected today</text> }
                                        else { <text>@Math.Abs(daysLeft) day(s) overdue</text> }
                                    </small>
                                }
                            }
                            else
                            {
                                <span class="text-muted">Not yet determined</span>
                            }
                        </p>
                    </div>
                    <div class="col-md-6">
                        <h6 class="text-muted">Last Updated</h6>
                        <p class="fs-5">@shipment.LastUpdated.ToString("MMM dd, yyyy h:mm tt") UTC</p>
                    </div>
                </div>

                <!-- Status timeline -->
                <hr />
                <h6 class="text-muted mb-3">Shipment Progress</h6>
                <div class="d-flex justify-content-between">
                    @foreach (var status in new[] { ShipmentStatus.Pending, ShipmentStatus.PickedUp, ShipmentStatus.InTransit, ShipmentStatus.OutForDelivery, ShipmentStatus.Delivered })
                    {
                        var isActive = shipment.Status >= status && shipment.Status != ShipmentStatus.Cancelled;
                        <div class="text-center flex-fill">
                            <div class="rounded-circle mx-auto d-flex align-items-center justify-content-center @(isActive ? "bg-success" : "bg-light border")"
                                 style="width: 40px; height: 40px;">
                                @if (isActive)
                                {
                                    <span class="text-white">✓</span>
                                }
                            </div>
                            <small class="@(isActive ? "fw-bold" : "text-muted")">@status</small>
                        </div>
                    }
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? shipment;
    private bool searched;
    private bool isSearching;

    private async Task HandleKeyUp(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isSearching = true;
        try
        {
            searchedNumber = trackingNumber.Trim();
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
            searched = true;
        }
        finally
        {
            isSearching = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

